  VALUES ?film { dbr:In_the_Beginning_There_Was_Underwear dbr:Une_famille_à_louer }
  ?film dbo:director ?director .
  OPTIONAL { ?director (dbo:birthDate|dbp:birthDate) ?birthDate . }
